/**
 * sprites.js - Zodiac pixel-art sprite data + renderer
 *
 * One grid size per animal type:
 *   Quadruped / Snake : 48 cols x 32 rows  (head LEFT, body extends right)
 *   Upright            : 32 cols x 48 rows  (face forward, head top)
 *
 * Colour index:
 *   0 = transparent
 *   1 = primary  (body fill)
 *   2 = secondary (eyes, snout, markings)
 *   3 = accent   (stripes, comb, ridges - primary darkened ~70%)
 */

/* global window */
